INSERT INTO faqs (question, answer, sort_order, active) VALUES
  ('Do you offer worldwide international delivery?', 'Yes, we provide tracked international courier delivery (DHL / FedEx Express / Air Cargo) to the United Kingdom, USA, Canada, Australia, UAE, Saudi Arabia, Europe and worldwide.', 1, true),
  ('Can I see a live video or ping demonstration of the bat before ordering?', 'Yes! We encourage all customers to message us on WhatsApp (+92 323 1438214) to view live high-definition videos, weight scale checks, and ping demonstrations of the exact bat.', 2, true),
  ('Do you provide custom bat making and personalized player specifications?', 'Yes. We handcraft bespoke bats tailored to your exact weight (e.g. 2lb 7oz to 2lb 12oz), handle shape (oval/round), edge depth (up to 45mm), and profile preference.', 3, true),
  ('What payment methods do you accept for international orders?', 'We accept Wise, Bank Transfer, Western Union, Remitly, MoneyGram, and TapTap Send with secure proof of payment confirmation.', 4, true),
  ('Do you offer machine knocking-in and bat preparation?', 'Yes, we offer professional machine knocking-in, oiling, scuff sheet fitting, and toe guard application upon request before dispatch.', 5, true);
INSERT INTO products (id, name, category, price, stock, right_stock, left_stock, image, images, description, featured, active, sort_order) VALUES
  ('beauty-processed-bats-silver-edition', 'Silver Edition', 'Beauty Processed Bats', 125, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/silver-edition/silver-beauty-processed-front-full-a.webp', '["/assets/products/bats/silver-edition/silver-beauty-processed-front-full-a.webp","/assets/products/bats/silver-edition/silver-beauty-processed-front-detail-a.webp","/assets/products/bats/silver-edition/silver-beauty-processed-front-detail-b.webp","/assets/products/bats/silver-edition/silver-beauty-processed-edge-profile-a.webp","/assets/products/bats/silver-edition/silver-beauty-processed-edge-profile-b.webp","/assets/products/bats/silver-edition/silver-beauty-processed-edge-toe-a.webp","/assets/products/bats/silver-edition/silver-beauty-processed-front-toe-detail.webp"]'::jsonb, 'Handcrafted by master bat-makers in Sialkot, the Silver Edition beauty-processed cricket bat combines traditional shaping with a refined cosmetic finish. Selected from premium English willow clefts, it features a pronounced spine, generous mid-to-low sweet spot, and substantial edge profiles tailored for stroke-makers on varied pitch surfaces. The bat is balanced for a light, effortless pickup, allowing rapid hand speed through the shot. Every photograph in this dedicated gallery showcases the actual bat, detailing its pristine face, toe finish, and edge contour. Available with worldwide delivery directly from our Sialkot facility. Contact us on WhatsApp for live ping demonstrations and exact weight confirmations before dispatch.', false, true, 1),
  ('beauty-processed-bats-player-edition', 'Player Edition', 'Beauty Processed Bats', 165, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bat-collection.webp', '["/assets/products/bat-collection.webp"]'::jsonb, 'The Player Edition beauty-processed cricket bat represents professional-grade craftsmanship straight from Sialkot''s heritage bat-making workshops. Built from top-tier clefts, this bat delivers an imposing profile with thick power edges and a full-bodied spine that maximizes rebound energy across the entire hitting zone. The balanced weight distribution ensures optimal pickup and fluid stroke control during aggressive front-foot drives or commanding back-foot cuts. Each cleft is precision-pressed and hand-finished with an immaculate aesthetic polish. We offer worldwide shipping with knocking-in options available upon request. Request a live video inspection on WhatsApp to verify grain structure, balance, and ping performance.', false, true, 2),
  ('beauty-processed-bats-bounce-edition', 'Bounce Edition', 'Beauty Processed Bats', 180, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/bounce-edition/bounce-front-a.webp', '["/assets/products/bats/bounce-edition/bounce-front-a.webp","/assets/products/bats/bounce-edition/bounce-front-b.webp","/assets/products/bats/bounce-edition/bounce-front-detail.webp","/assets/products/bats/bounce-edition/bounce-reverse.webp","/assets/products/bats/bounce-edition/bounce-edge-a.webp","/assets/products/bats/bounce-edition/bounce-edge-b.webp"]'::jsonb, 'Engineered specifically for high-rebound energy and responsive stroke play, the Bounce Edition beauty-processed bat is sculpted from seasoned clefts in Sialkot. Featuring an enhanced mid-blade sweet spot, extended power zone, and robust edge thickness, it offers immense punch for modern boundary hitters. The profile is tapered to maintain a feather-light pickup without sacrificing blade mass or structural integrity. The authentic multi-angle gallery highlights the bat''s clean face, reverse camber, and reinforced toe. Shipped worldwide with secure packaging. Message our Sialkot team on WhatsApp to receive a live ping test video and personalized balance consultation.', false, true, 3),
  ('beauty-processed-bats-apex-pro', 'Apex Pro', 'Beauty Processed Bats', 185, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/apex-edition/apex-pro-front-a.webp', '["/assets/products/bats/apex-edition/apex-pro-front-a.webp","/assets/products/bats/apex-edition/apex-pro-front-b.webp","/assets/products/bats/apex-edition/apex-pro-reverse.webp","/assets/products/bats/apex-edition/apex-pro-edge-a.webp","/assets/products/bats/apex-edition/apex-pro-edge-b.webp","/assets/products/bats/apex-edition/apex-pro-profile-detail.webp","/assets/products/bats/apex-edition/apex-pro-toe-front.webp","/assets/products/bats/apex-edition/apex-pro-toe-reverse.webp"]'::jsonb, 'The Apex Pro beauty-processed cricket bat is our flagship performance model, crafted in Sialkot for discerning cricketers who demand supreme power and precision balance. Hand-shaped with commanding 40mm+ edge contours, an elevated spine, and an expansive sweet spot, this bat provides explosive rebound on drives, pulls, and aerial strokes. The premium cane handle absorbs impact shock effortlessly, providing unmatched feel and feedback at the crease. Accompanied by its matching protective cover, the complete gallery reflects the exact blade profile, toe angles, and clean grain finish. Delivered worldwide. Connect on WhatsApp for live video reviews, ping trials, and custom knocking-in services.', true, true, 4),
  ('beauty-processed-bats-monster-series', 'Monster Series', 'Beauty Processed Bats', 195, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/monster-series/monster-front-a.webp', '["/assets/products/bats/monster-series/monster-front-a.webp","/assets/products/bats/monster-series/monster-front-b.webp","/assets/products/bats/monster-series/monster-reverse.webp","/assets/products/bats/monster-series/monster-edge-a.webp","/assets/products/bats/monster-series/monster-edge-b.webp","/assets/products/bats/monster-series/monster-weight-proof.webp"]'::jsonb, 'The Monster Series beauty-processed cricket bat is crafted for heavy-hitting power batsmen who demand maximum willow mass and destructive hitting power. Hand-sculpted in Sialkot with an ultra-thick edge profile, high spine, and deep power belly, this bat delivers immense momentum through the contact zone. Despite its imposing dimensions, meticulous pressing and balance distribution ensure a comfortable pickup and controlled bat flow. The gallery includes comprehensive weight-proof verification, face angles, and edge measurements. Dispatched internationally to cricket clubs and players worldwide. Contact our Sialkot workshop via WhatsApp for live bat trials and weight specifications.', false, true, 5),
  ('beauty-processed-bats-special-edition', 'Special Edition', 'Beauty Processed Bats', 215, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/special-edition/special-edition-front-a.webp', '["/assets/products/bats/special-edition/special-edition-front-a.webp","/assets/products/bats/special-edition/special-edition-front-b.webp","/assets/products/bats/special-edition/special-edition-front-c.webp","/assets/products/bats/special-edition/special-edition-reverse.webp","/assets/products/bats/special-edition/special-edition-edge.webp"]'::jsonb, 'The Special Edition beauty-processed bat showcases precision craftsmanship and refined blade finishing from our Sialkot workshop. Selected for structural density and straight grain alignment, this cleft features a full, traditional profile with substantial edges and an elongated hitting zone suitable for all-format cricket. The semi-oval cane handle provides superior grip stability and shock dampening during long innings. The exclusive product gallery illustrates the bat from multiple perspectives, including edge depth, back profile, and toe geometry. We provide reliable worldwide shipping. Contact us on WhatsApp to inspect ping performance and current workshop availability.', false, true, 6),
  ('beauty-processed-bats-vvip-bat', 'VVIP Bat', 'Beauty Processed Bats', 245, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/vvip-bat/vvip-45mm-front-a.webp', '["/assets/products/bats/vvip-bat/vvip-45mm-front-a.webp","/assets/products/bats/vvip-bat/vvip-45mm-front-b.webp","/assets/products/bats/vvip-bat/vvip-45mm-reverse.webp","/assets/products/bats/vvip-bat/vvip-45mm-profile-a.webp","/assets/products/bats/vvip-bat/vvip-45mm-edge-a.webp","/assets/products/bats/vvip-bat/vvip-45mm-edge-b.webp","/assets/products/bats/vvip-bat/vvip-45mm-measurement.webp"]'::jsonb, 'The VVIP beauty-processed cricket bat is an elite custom profile featuring massive 45mm edges and a towering spine engineered for boundary-clearing performance. Handcrafted by master artisans in Sialkot, this bat packs immense willow behind the sweet spot while maintaining exceptional balance and swing velocity. The cleft undergoes specialized pressing to ensure solid blade compression, longevity, and explosive acoustic ping. The gallery includes exact edge measurement views, face profiles, and back contours of this specific model. Delivered internationally with complete transit protection. Request a live WhatsApp video consultation for bat-ping verification and customized preparation.', false, true, 7),
  ('bonafide-bats-vvip-bonafide-original-grade-a', 'VVIP Bonafide Original - Grade A+', 'Bonafide Bats', 499, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/vvip-bonafide-original-front-a.webp', '["/assets/products/vvip-bonafide-original-front-a.webp","/assets/products/vvip-bonafide-original-front-b.webp","/assets/products/vvip-bonafide-original-edge.webp","/assets/products/vvip-bonafide-original-back.webp"]'::jsonb, 'The VVIP Bonafide Original Grade A+ is our most prestigious cricket bat, crafted from unbleached, natural Grade A+ English willow in Sialkot. Presented in its raw, unprocessed state, this cleft displays tight, straight, and evenly spaced grains across a pristine face. Built with massive power edges, a commanding mid-blade swell, and a balanced duckbill toe taper, it delivers instantaneous ping and unmatched driving power. Every photograph in this exclusive gallery depicts the authentic blade, unvarnished willow texture, and natural grain structure. Available for immediate worldwide dispatch. Contact us on WhatsApp for a live high-definition video inspection, ping test, and knocking-in service.', true, true, 8),
  ('bonafide-bats-special-edition-grade-a', 'Special Edition - Grade A', 'Bonafide Bats', 330, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/bonafide-special-grade-a/special-edition-grade-a-front.webp', '["/assets/products/bats/bonafide-special-grade-a/special-edition-grade-a-front.webp","/assets/products/bats/bonafide-special-grade-a/special-edition-grade-a-front-detail.webp","/assets/products/bats/bonafide-special-grade-a/special-edition-grade-a-reverse.webp","/assets/products/bats/bonafide-special-grade-a/special-edition-grade-a-edge-a.webp","/assets/products/bats/bonafide-special-grade-a/special-edition-grade-a-edge-b.webp","/assets/products/bats/bonafide-special-grade-a/special-edition-grade-a-toe.webp"]'::jsonb, 'The Bonafide Special Edition Grade A cricket bat is crafted from unbleached Grade A English willow, showcasing natural wood grains and authentic Sialkot craftsmanship. Designed with a full-bodied profile, generous edges, and a pronounced sweet spot, it offers outstanding rebound resilience and balanced pickup for stroke-makers. The natural wood finish emphasizes the structural integrity and density of the cleft. The gallery captures the actual bat from every angle, including face details, reverse contour, and toe construction. Shipped worldwide with premium protective packaging. Reach out on WhatsApp to view live ping demonstrations and confirm exact bat weights.', false, true, 9),
  ('bonafide-bats-player-edition', 'Player Edition', 'Bonafide Bats', 215, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/bonafide-player-edition/player-edition-bonafide-front-a.webp', '["/assets/products/bats/bonafide-player-edition/player-edition-bonafide-front-a.webp","/assets/products/bats/bonafide-player-edition/player-edition-bonafide-front-b.webp","/assets/products/bats/bonafide-player-edition/player-edition-bonafide-front-detail.webp","/assets/products/bats/bonafide-player-edition/player-edition-bonafide-reverse.webp","/assets/products/bats/bonafide-player-edition/player-edition-bonafide-edge-a.webp","/assets/products/bats/bonafide-player-edition/player-edition-bonafide-edge-b.webp","/assets/products/bats/bonafide-player-edition/player-edition-bonafide-toe-front.webp","/assets/products/bats/bonafide-player-edition/player-edition-bonafide-toe-reverse.webp"]'::jsonb, 'The Bonafide Player Edition cricket bat is constructed from hand-selected natural English willow in Sialkot, preserving the organic beauty and grain alignment of the cleft. Featuring a traditional profile with thick edges and a well-positioned middle, it provides substantial power for front-foot drives and back-foot defence. The multi-piece cane handle delivers excellent vibration absorption and tactile feedback. Accompanied by its custom black bat cover, the gallery displays only the authentic Player Edition model. Delivered worldwide to international cricketers and leagues. Contact our Sialkot team on WhatsApp for live ping videos and custom weight selection.', false, true, 10),
  ('junior-and-harrow-bats-size-4', 'Size 4', 'Junior & Harrow Bats', 70, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/size-4/size-4-front-detail.webp', '["/assets/products/bats/size-4/size-4-front-detail.webp"]'::jsonb, 'The Size 4 junior cricket bat is specially designed in Sialkot for young aspiring cricketers developing their stroke technique. Scaled to proportionate junior dimensions, it offers a lightweight pickup, narrow handle diameter, and a balanced sweet spot that enables young batters to play full attacking shots with confidence. Hand-finished with clean edges and smooth blade contouring, it provides authentic willow response. The gallery presents the exact original product photograph. Dispatched worldwide to junior academies and clubs. Message our Sialkot team on WhatsApp to confirm size suitability and junior equipment bundles.', false, true, 11),
  ('junior-and-harrow-bats-size-5', 'Size 5', 'Junior & Harrow Bats', 85, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/size-5/size-5-weight-0740.webp', '["/assets/products/bats/size-5/size-5-weight-0740.webp","/assets/products/bats/size-5/size-5-weight-0700-a.webp","/assets/products/bats/size-5/size-5-weight-0700-b.webp","/assets/products/bats/size-5/size-5-pair-front.webp","/assets/products/bats/size-5/size-5-pair-reverse.webp","/assets/products/bats/size-5/size-5-profile-and-front.webp"]'::jsonb, 'Crafted for growing junior players, the Size 5 cricket bat from Sialkot delivers the ideal combination of lightweight manoeuvrability and solid striking power. Shaped with proportionate edges, a balanced spine, and an ergonomic handle, it allows young cricketers to build correct batting fundamentals and timing without straining their wrists. The gallery features verified batch photographs, including weight-scale verification (approx. 700g–740g) and profile views. Available with worldwide international shipping. Connect with us on WhatsApp for weight selection and junior equipment advice.', false, true, 12),
  ('junior-and-harrow-bats-size-6', 'Size 6', 'Junior & Harrow Bats', 105, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/harrow-original/harrow-original-front.webp', '["/assets/products/bats/harrow-original/harrow-original-front.webp","/assets/products/bats/harrow-original/harrow-original-reverse.webp","/assets/products/bats/harrow-original/harrow-original-edge-a.webp","/assets/products/bats/harrow-original/harrow-original-edge-b.webp"]'::jsonb, 'The Size 6 junior cricket bat bridges intermediate youth cricket and senior equipment, handcrafted in Sialkot from quality willow clefts. It features extended blade dimensions, substantial edge thickness, and a responsive sweet spot engineered to help youth batsmen generate boundary power effortlessly. The multi-piece cane handle dampens ball impact vibrations for maximum comfort. Original product photographs illustrate the genuine handle geometry, face profile, and clean finish. Shipped worldwide to clubs and academies. Inquire on WhatsApp for current stock availability, knocking-in, and dispatch details.', false, true, 13),
  ('junior-and-harrow-bats-harrow-size', 'Harrow Size', 'Junior & Harrow Bats', 110, 'Confirm on WhatsApp', NULL, NULL, '/assets/products/bats/harrow-original/harrow-original-front.webp', '["/assets/products/bats/harrow-original/harrow-original-front.webp","/assets/products/bats/harrow-original/harrow-original-reverse.webp","/assets/products/bats/harrow-original/harrow-original-edge-a.webp","/assets/products/bats/harrow-original/harrow-original-edge-b.webp"]'::jsonb, 'Tailored for teenagers and senior youth players transitioning to full-size bats, the Harrow Size cricket bat offers near-senior blade dimensions with a slightly shorter handle and reduced weight. Handcrafted in Sialkot, it boasts thick power edges, a responsive mid-blade swell, and feather-light pickup for aggressive shot execution. The gallery showcases unedited product photographs detailing blade geometry and authentic craftsmanship. Dispatched internationally with secure delivery. Contact our Sialkot bat-makers on WhatsApp to request a live ping demonstration and custom balance consultation.', false, true, 14),
  ('batting-pads-dsc-krunch-300', 'DSC Krunch 300', 'Batting Pads', 28, '6', '5', '1', '/assets/products/item-000.webp', '["/assets/products/item-000.webp"]'::jsonb, 'The DSC Krunch 300 batting pads offer robust front-line protection and agile movement for competitive batsmen. Constructed with lightweight high-density foam rods reinforced with a traditional cane front, these pads effectively dissipate high-speed ball impacts. The ergonomically sculpted knee bolster cradles the joint snugly, while wide padded calf and ankle straps ensure a secure, non-slip fit during fast running between the wickets. Finished in durable PU facing with abrasion-resistant instep piping. Shipped worldwide with verified stock. Contact Sialkot Cricket Kits on WhatsApp for sizing confirmations and kit combinations.', false, true, 15),
  ('batting-pads-gm-b555-diamond', 'GM B555 Diamond', 'Batting Pads', 29, '6', '6', '0', '/assets/products/item-001.webp', '["/assets/products/item-001.webp"]'::jsonb, 'Designed in collaboration with modern match requirements, the GM B555 Diamond batting pads feature an advanced seven-cane vertical construction backed by dual-density impact foam. The pre-curved knee roll provides anatomical alignment and superior protection against direct deliveries. Breathable air-mesh vertical bolsters enhance ventilation during lengthy innings under the sun. Reinforced knee locator cups and durable instep bindings prevent premature ground wear. Available for international dispatch directly from Sialkot. Reach out on WhatsApp for real-time stock verification and club order inquiries.', false, true, 16),
  ('batting-pads-gray-nicolls-legend', 'Gray-Nicolls Legend', 'Batting Pads', 32, '7', '4', '3', '/assets/products/item-007.webp', '["/assets/products/item-007.webp"]'::jsonb, 'The Gray-Nicolls Legend batting pads represent the pinnacle of traditional elegance and contemporary impact defense. Engineered with premium multi-section cane uprights and high-density foam wing wraps, they deliver comprehensive protection across the shins, knees, and lower leg. The luxury leather-look PU skin offers easy wipe-clean durability, while the cushioned knee cup incorporates soft-feel moisture-wicking lining for exceptional match comfort. Available in both right-handed and left-handed configurations. Shipped worldwide from Sialkot with full transit security. Message our WhatsApp desk for stock confirmation.', false, true, 17),
  ('batting-pads-kookaburra-ghost', 'Kookaburra Ghost', 'Batting Pads', 29, '1', '0', '1', '/assets/products/item-008.webp', '["/assets/products/item-008.webp"]'::jsonb, 'The Kookaburra Ghost batting pads feature a clean, all-white minimalist aesthetic matched with elite lightweight impact absorption. Built with micro-weight HDF cane ribs and a three-piece external knee roll, these pads minimize drag and facilitate quick singles. The internal vertical bolster utilizes breathable foam padding with moisture-management fabric to keep the batter cool and focused. Features durable synthetic toe piping for enhanced longevity on turf and synthetic wickets. Shipped internationally from our Sialkot hub. Contact us on WhatsApp for live product visuals and availability.', false, true, 18),
  ('batting-pads-new-balance-tc-1260', 'New Balance TC 1260', 'Batting Pads', 29, '6', '6', '0', '/assets/products/item-010.webp', '["/assets/products/item-010.webp"]'::jsonb, 'The New Balance TC 1260 batting pads combine cutting-edge styling with tour-level impact resistance. Featuring a robust combination of traditional cane shielding and advanced cross-linked foam panels, they cushion severe bowling impacts effortlessly. The deep three-section knee cup provides flexible articulation, preventing the pad from riding up during deep stances or dynamic sweeps. Wide cushioned straps with heavy-duty touch fasteners provide a tailored, distraction-free fit. Available with worldwide delivery. Inquire via WhatsApp for current stock and cricket equipment bundles.', false, true, 19),
  ('batting-pads-sf-maximum-players', 'SF Maximum Players', 'Batting Pads', 28, '5', '4', '1', '/assets/products/item-011.webp', '["/assets/products/item-011.webp"]'::jsonb, 'Engineered for serious league and club cricketers, the SF Maximum Players batting pads provide high-level protection across the front and side of the leg. Constructed with shock-absorbing cane rods encased in high-density foam padding, they ensure maximum energy absorption against pace bowling. The pre-moulded knee bolster offers firm stabilization and smooth flex during running. Extra-wide calf straps distribute pressure evenly for long-lasting comfort. Supplied directly from Sialkot with international delivery. Contact us on WhatsApp to verify sizing and stock.', false, true, 20),
  ('batting-pads-sg-white-edition', 'SG White Edition', 'Batting Pads', 28, '3', '2', '1', '/assets/products/item-012.webp', '["/assets/products/item-012.webp"]'::jsonb, 'The SG White Edition batting pads deliver classic protection and clean aesthetics for opening and middle-order batsmen. Featuring a traditional flat-front design with reinforced cane pillars and high-resilience foam, these pads absorb heavy ball impacts reliably. The cushioned side wing provides extended wraparound protection for the calf, while the soft foam ankle cup eliminates chafing. Fitted with premium PU facing and reinforced instep fabric for prolonged service life. Shipped worldwide from Sialkot. Reach out on WhatsApp for fast stock confirmations.', false, true, 21),
  ('batting-pads-gm-maxi-606-white', 'GM Maxi 606 White', 'Batting Pads', 28, '2', '2', '0', '/assets/products/item-006.webp', '["/assets/products/item-006.webp"]'::jsonb, 'The GM Maxi 606 White batting pads provide an excellent blend of lightweight mobility and dependable defensive shielding. Built with a modern vertical cane framework layered over high-density foam, they offer solid protection against medium-fast and spin bowling. The breathable vertical bolster promotes active airflow, reducing sweat buildup during prolonged spells at the crease. Padded nylon straps with quick-release velcro tabs ensure easy adjustment and reliable security. Dispatched worldwide from Sialkot. WhatsApp us to check current stock and delivery schedules.', false, true, 22),
  ('batting-pads-ss-players-edition', 'SS Players Edition', 'Batting Pads', 32, '2', '0', '2', '/assets/products/item-002.webp', '["/assets/products/item-002.webp"]'::jsonb, 'The SS Players Edition batting pads are crafted to meet the stringent demands of top-tier cricket competition. Utilizing high-grade lightweight cane ribs and multi-layer shock foam, they offer maximum protection without imposing unnecessary leg weight. The contoured knee socket features cushioned side wings that shield the sensitive knee ligaments from angled deflections. Covered in premium polyurethane with reinforced piping along the bottom rim for turf resistance. Available with worldwide dispatch. Inquire on WhatsApp for current right and left-hand stock.', false, true, 23),
  ('batting-pads-gray-nicolls-stratos', 'Gray-Nicolls Stratos', 'Batting Pads', 30, '7', '5', '2', '/assets/products/item-003.webp', '["/assets/products/item-003.webp"]'::jsonb, 'Featuring modern angular styling and lightweight protective architecture, the Gray-Nicolls Stratos batting pads are built for dynamic run-scorers. The hybrid construction incorporates high-density cane ribs and sculpted foam side wings for all-round coverage. A multi-layered knee locator ensures the pad moves naturally with the batsman''s stride, avoiding bulky interference during running. The durable PU outer shell resists scuffing and cleans effortlessly. Delivered worldwide from our Sialkot warehouse. Contact us on WhatsApp for sizing guidance.', false, true, 24),
  ('batting-pads-gm-maxi-606', 'GM Maxi 606', 'Batting Pads', 28, '4', '3', '1', '/assets/products/item-004.webp', '["/assets/products/item-004.webp"]'::jsonb, 'The GM Maxi 606 batting pads deliver dependable protection, balanced weight distribution, and functional comfort for club and league cricketers. Engineered with traditional cane reinforcement over shock-absorbing foam cores, they provide dependable defense against pace bowling. The soft padded knee cup and moisture-resistant internal lining keep the legs comfortable throughout demanding match situations. Strong velcro straps provide a secure, tailored hold on both right and left-handed batsmen. Shipped internationally from Sialkot. Connect on WhatsApp to confirm availability.', false, true, 25),
  ('batting-pads-moulded-pads-white', 'Moulded Pads - White', 'Batting Pads', 26, '2', '-', '-', '/assets/products/item-123.webp', '["/assets/products/item-123.webp"]'::jsonb, 'The Moulded Batting Pads in classic white utilize modern thermo-formed foam technology to deliver ultra-lightweight, ergonomic protection. The single-piece moulded shell wraps snugly around the shin and knee, providing zero-bulk aerodynamic efficiency for quick singles and sharp running. Dual-density internal padding absorbs high-impact energy while the sweat-wicking lining prevents moisture buildup. Durable outer skin resists dirt and turf stains. Shipped internationally from Sialkot. Contact us on WhatsApp to discuss bulk club orders or individual stock.', false, true, 26),
  ('batting-pads-moulded-pads-black', 'Moulded Pads - Black', 'Batting Pads', 26, '2', '-', '-', '/assets/products/item-124.webp', '["/assets/products/item-124.webp"]'::jsonb, 'Designed for modern T20 leagues, coloured-clothing matches, and training sessions, these Black Moulded Batting Pads combine modern aesthetics with high-performance impact defense. The pre-curved lightweight moulded shell eliminates traditional cane bulk, providing complete freedom of movement at the crease. Soft internal foam dampens impact vibrations, while the quick-adjust strap system ensures a snug, non-slip fit on the leg. Shipped worldwide directly from Sialkot. Message our WhatsApp team to verify stock and shipping rates.', false, true, 27),
