  ('helmets-masuri-helmet-black', 'Masuri Helmet - Black', 'Helmets', 35, '1', NULL, NULL, '/assets/products/helmet-masuri-black.webp', '["/assets/products/helmet-masuri-black.webp"]'::jsonb, 'The Masuri Black cricket helmet represents industry-standard head protection, featuring Masuri''s signature steel grille and high-impact outer shell. The dual-density inner foam cushions severe impacts while integrated ventilation channels prevent overheating during long batting spells. Shipped worldwide from Sialkot. Message our WhatsApp team for size and stock verification.', false, true, 122),
  ('waterproof-caps-nike-waterproof-cap', 'Nike Waterproof Cap', 'Waterproof Caps', 10, '8', NULL, NULL, '/assets/products/item-103.webp', '["/assets/products/item-103.webp"]'::jsonb, 'The Nike Waterproof Cap is crafted from high-performance water-repellent micro-poly fabric, designed to shield cricketers from light rain and intense sun during outdoor training and matches. Features breathable side eyelets, an internal moisture-wicking sweatband, and an adjustable rear strap with a metal buckle for a secure, custom fit. The structured pre-curved visor provides crisp glare protection in bright conditions. Dispatched worldwide directly from Sialkot. Contact our WhatsApp desk for stock checks and club orders.', false, true, 123),
  ('waterproof-caps-under-armour-waterproof-cap', 'Under Armour Waterproof Cap', 'Waterproof Caps', 10, '7', NULL, NULL, '/assets/products/item-105.webp', '["/assets/products/item-105.webp"]'::jsonb, 'The Under Armour Waterproof Cap delivers lightweight weather protection with a moisture-resistant outer finish and quick-drying internal sweatband. Engineered with breathable woven fabric and embroidered ventilation eyelets, it keeps the head cool during demanding outdoor cricket drills. The adjustable back closure ensures a stable hold in windy weather. Delivered internationally from Sialkot. Inquire on WhatsApp for availability.', false, true, 124),
  ('waterproof-caps-north-face-waterproof-cap', 'North Face Waterproof Cap', 'Waterproof Caps', 10, '5', NULL, NULL, '/assets/products/item-104.webp', '["/assets/products/item-104.webp"]'::jsonb, 'The North Face Waterproof Cap combines outdoor-grade water repellency with breathable athletic fabric for reliable weather shielding during cricket sessions and coaching duties. The lightweight, packable construction features a pre-curved bill to block harsh sunlight, while the adjustable rear strap accommodates all head sizes. Dispatched worldwide from Sialkot. Message on WhatsApp for stock confirmations.', false, true, 125),
  ('waterproof-caps-icon-waterproof-cap', 'Icon Waterproof Cap', 'Waterproof Caps', 10, '7', NULL, NULL, '/assets/products/item-102.webp', '["/assets/products/item-102.webp"]'::jsonb, 'The Icon Waterproof Cap offers sleek weather-resistant construction, durable stitching, and a comfortable moisture-wicking headband for outdoor cricket activities. Pre-curved bill blocks sun glare effectively while the water-repellent outer layer prevents rain soaking. Features an adjustable back tab for personalized sizing. Shipped worldwide from Sialkot. Reach out on WhatsApp for fast stock updates.', false, true, 126),
  ('waterproof-caps-adidas-waterproof-cap', 'Adidas Waterproof Cap', 'Waterproof Caps', 10, '8', NULL, NULL, '/assets/products/item-101.webp', '["/assets/products/item-101.webp"]'::jsonb, 'The Adidas Waterproof Cap features water-repellent performance fabric, classic athletic styling, and an adjustable closure for all-day comfort during cricket training and coaching sessions. Integrated ventilation eyelets facilitate continuous heat dissipation, while the cushioned inner headband absorbs sweat. Delivered worldwide from Sialkot. Contact our WhatsApp desk for stock availability.', false, true, 127),
  ('keeping-guards-sg-keeping-guard', 'SG Keeping Guard', 'Keeping Guards', 4, '30', NULL, NULL, '/assets/products/item-106.webp', '["/assets/products/item-106.webp"]'::jsonb, 'The SG Keeping Guard provides essential groin protection for wicketkeepers and close fielders, engineered with high-impact moulded polymer and soft rubberized perimeter padding for comfortable anatomical positioning during deep crouching and sudden lateral movements. Fits securely into all standard supporter pouches and briefs. Dispatched worldwide from Sialkot. Inquire via WhatsApp for stock confirmations.', false, true, 128),
  ('keeping-guards-gm-keeping-guard', 'GM Keeping Guard', 'Keeping Guards', 4, '23', NULL, NULL, '/assets/products/item-107.webp', '["/assets/products/item-107.webp"]'::jsonb, 'The GM Keeping Guard delivers dependable impact shielding with an ergonomically contoured polymer cup and cushioned perimeter edges to prevent chafing during active wicketkeeping and close catching. Lightweight yet rigid construction disperses direct impacts away from sensitive areas. Shipped worldwide from Sialkot. Contact on WhatsApp for stock checks.', false, true, 129),
  ('keeping-guards-gray-nicolls-keeping-guard', 'Gray-Nicolls Keeping Guard', 'Keeping Guards', 5, '19', NULL, NULL, '/assets/products/item-108.webp', '["/assets/products/item-108.webp"]'::jsonb, 'The Gray-Nicolls Keeping Guard combines high-strength moulded defense with a soft silicone outer rim for maximum comfort and security behind the stumps. Designed to allow complete flexibility during standing up to spinners and diving takes without pinching. Delivered worldwide from Sialkot. Message on WhatsApp for availability.', false, true, 130),
  ('other-accessories-sf-batting-inner-gloves', 'SF Batting Inner Gloves', 'Other Accessories', 7, '25', NULL, NULL, '/assets/products/item-111.webp', '["/assets/products/item-111.webp"]'::jsonb, 'The SF Batting Inner Gloves are crafted from soft, 100% breathable cotton to absorb hand perspiration, enhance bat grip traction, and prevent blisters inside batting gloves. Elasticated cuffs provide a snug, non-slip fit around the wrists while extending the lifespan of your primary leather batting gloves. Shipped worldwide from Sialkot. Contact on WhatsApp for stock checks.', false, true, 131),
  ('other-accessories-guard-underwear', 'Guard Underwear', 'Other Accessories', 7, 'Available', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Guard Underwear supporter features comfortable, breathable stretch cotton construction with an integrated secure front pouch designed to hold protective abdo guards firmly in place during active running and bowling. The wide elasticated waistband prevents rolling or slipping during intense match play. Dispatched worldwide from Sialkot. Inquire on WhatsApp for sizing advice.', false, true, 132),
  ('teamwear-gray-nicolls-playing-kit-small', 'Gray-Nicolls Playing Kit - Small', 'Teamwear', 25, '33', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Playing Kit in Size Small is crafted from lightweight, high-performance moisture-wicking polyester engineered to keep club cricketers cool and dry during intense match conditions. Featuring ergonomic raglan sleeves, breathable underarm micro-mesh panels, and a traditional cricket shirt collar, it delivers unrestricted freedom of movement for fast bowling, diving in the field, and running between wickets. The matching trousers incorporate an elasticated drawstring waistband and reinforced knee panels for durability on all pitch surfaces. Dispatched worldwide directly from our Sialkot facility. Contact our WhatsApp desk for team crest printing, custom numbering, and club order assistance.', false, true, 133),
  ('teamwear-gray-nicolls-playing-kit-medium', 'Gray-Nicolls Playing Kit - Medium', 'Teamwear', 25, '22', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Playing Kit in Size Medium delivers professional-standard cricket teamwear performance, utilizing advanced technical polyester fabric for rapid perspiration evaporation. Tailored with a comfortable athletic cut, the shirt allows complete shoulder articulation during bowling and throwing, while the breathable trousers provide optimal comfort through long fielding sessions. Heavy-duty flat-lock stitching prevents chafing and ensures lasting durability across full playing seasons. Supplied directly from Sialkot with international delivery. Reach out on WhatsApp for size confirmations and club kit customization.', false, true, 134),
  ('teamwear-gray-nicolls-playing-kit-large', 'Gray-Nicolls Playing Kit - Large', 'Teamwear', 26, '17', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Playing Kit in Size Large combines high-grade breathable polyester with comfortable athletic tailoring for senior club cricketers. The moisture-management fabric actively pulls sweat away from the skin, maintaining core comfort under demanding match conditions. Reinforced collar construction and tear-resistant fabric withstand diving in the outfield and aggressive sliding. Dispatched worldwide from Sialkot with secure packaging. Message our WhatsApp team for bulk academy orders, custom club embroidery, and fast dispatch schedules.', false, true, 135),
  ('teamwear-gray-nicolls-playing-kit-x-large', 'Gray-Nicolls Playing Kit - X-Large', 'Teamwear', 26, '12', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Playing Kit in Size X-Large provides generous athletic sizing, moisture-management fabric, and breathable underarm panels for optimal airflow during hot match days. Built with quick-drying synthetic fibers that resist creasing and maintain crisp team presentation throughout multi-day tournaments. Features comfortable elasticated trouser waist with drawstring adjustability. Available for international delivery directly from our Sialkot warehouse. Inquire on WhatsApp for teamwear bundle discounts and worldwide shipping rates.', false, true, 136),
  ('teamwear-gray-nicolls-playing-kit-xxl', 'Gray-Nicolls Playing Kit - XXL', 'Teamwear', 28, '21', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Playing Kit in Size XXL offers comfortable, non-restrictive sizing with technical moisture-wicking fabric engineered for demanding match conditions. Designed with reinforced stress points, ventilated side gussets, and soft-touch neck tape for maximum comfort throughout long overs in the field. Dispatched worldwide from Sialkot. Reach out on WhatsApp to verify measurements and discuss club requirements.', false, true, 137),
  ('teamwear-gray-nicolls-shorts-small', 'Gray-Nicolls Shorts - Small', 'Teamwear', 10, '25', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Shorts in Size Small are made from lightweight, quick-drying performance fabric with an elasticated drawstring waistband for a secure, custom fit during cricket training, gym sessions, and warm-ups. Features deep side pockets to hold practice cricket balls and training accessories. Breathable side panels maximize airflow and mobility. Dispatched worldwide from Sialkot. Contact us on WhatsApp for fast stock confirmations.', false, true, 138),
  ('teamwear-gray-nicolls-shorts-medium', 'Gray-Nicolls Shorts - Medium', 'Teamwear', 10, '24', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Shorts in Size Medium feature breathable athletic fabric, deep side pockets, and flexible side split seams for unrestricted agility during warm-ups and fielding drills. Designed with a wide elasticated waistband and internal drawcord to ensure non-slip positioning during sprints. Shipped worldwide from Sialkot. Inquire on WhatsApp for teamwear orders.', false, true, 139),
  ('teamwear-gray-nicolls-shorts-large', 'Gray-Nicolls Shorts - Large', 'Teamwear', 10, '25', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Shorts in Size Large deliver lightweight comfort, durable polyester construction, and an adjustable waistband for training sessions, coaching, and casual club wear. Reinforced pocket stitching securely holds accessories, while the moisture-wicking fabric keeps you dry during high-intensity workouts. Delivered internationally from Sialkot. Message on WhatsApp for stock updates.', false, true, 140),
  ('teamwear-gray-nicolls-shorts-x-large', 'Gray-Nicolls Shorts - X-Large', 'Teamwear', 10, '25', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Gray-Nicolls Shorts in Size X-Large provide a comfortable, relaxed fit with sweat-wicking fabric and secure pocket storage for coaching and training activities. Breathable lightweight material prevents overheating during long sessions under the sun. Available for worldwide delivery from Sialkot. Contact our WhatsApp desk for stock checks.', false, true, 141),
  ('teamwear-supreme-shorts-small', 'Supreme Shorts - Small', 'Teamwear', 8, '50', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Supreme Shorts in Size Small offer lightweight athletic comfort, breathable polyester fabric, and an elasticated waistband with drawstring for training and practice. Built with deep side storage pockets and reinforced seam construction for long-lasting durability on and off the field. Dispatched worldwide from Sialkot. Inquire on WhatsApp for availability.', false, true, 142),
  ('teamwear-supreme-shorts-medium', 'Supreme Shorts - Medium', 'Teamwear', 8, '29', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Supreme Shorts in Size Medium are designed for active cricket training, featuring durable, moisture-wicking fabric and deep side pockets for balls and accessories. Ergonomic athletic cut facilitates deep lunges, sprints, and fielding drills without binding. Shipped worldwide from Sialkot. Contact on WhatsApp for stock confirmations.', false, true, 143),
  ('teamwear-supreme-shorts-large', 'Supreme Shorts - Large', 'Teamwear', 8, '13', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Supreme Shorts in Size Large provide a flexible, comfortable fit with durable stitching and quick-drying athletic fabric for all sporting sessions. The wide waistband distributes pressure evenly, while the lightweight fabric ensures effortless mobility. Delivered worldwide from Sialkot. Message on WhatsApp for stock updates.', false, true, 144),
  ('teamwear-supreme-shorts-x-large', 'Supreme Shorts - X-Large', 'Teamwear', 8, '35', NULL, NULL, '/assets/brand/sialkot-cricket-kits-logo.png', '["/assets/brand/sialkot-cricket-kits-logo.png"]'::jsonb, 'The Supreme Shorts in Size X-Large offer generous sizing, breathable lightweight material, and an adjustable drawstring waist for post-match and training comfort. Reinforced pocket seams provide practical everyday utility for players and coaches alike. Shipped worldwide from Sialkot. Inquire via WhatsApp for teamwear orders.', false, true, 145);
